<?= $this->extend('admin/layouts/main') ?><?= $this->section('content') ?><h1 class="h3 mb-4"><?= esc($title) ?></h1><form class="card border-0 p-4" method="post" action="<?= $zone?site_url('admin/delivery-zones/'.$zone['id']):site_url('admin/delivery-zones') ?>"><?= csrf_field() ?><?php if($zone): ?><input type="hidden" name="_method" value="PUT"><?php endif ?><div class="row g-3"><div class="col-md-6"><label class="form-label">Name *</label><input class="form-control" name="name" value="<?= esc(old('name',$zone['name']??'')) ?>" required></div><div class="col-md-3"><label class="form-label">Zone Type *</label><select class="form-select" name="zone_type" id="zoneType"><?php foreach(['all_bangladesh'=>'All Bangladesh','district'=>'District','upazila'=>'Upazila'] as $v=>$l): ?><option value="<?= $v ?>" <?= old('zone_type',$zone['zone_type']??'all_bangladesh')===$v?'selected':'' ?>><?= $l ?></option><?php endforeach ?></select></div><div class="col-md-3"><label class="form-label">Status</label><select class="form-select" name="status"><option value="active" <?= old('status',$zone['status']??'active')==='active'?'selected':'' ?>>Active</option><option value="inactive" <?= old('status',$zone['status']??'')==='inactive'?'selected':'' ?>>Inactive</option></select></div><div class="col-md-6 location-field"><label class="form-label">District</label><select class="form-select" name="district_id" id="zoneDistrict"><option value="">Select district</option><?php foreach($districts as $d): ?><option value="<?= $d['id'] ?>" <?= (string)old('district_id',$zone['district_id']??'')===(string)$d['id']?'selected':'' ?>><?= esc($d['name_en'].' — '.$d['name_bn']) ?></option><?php endforeach ?></select></div><div class="col-md-6 upazila-field"><label class="form-label">Upazila</label><select class="form-select" name="upazila_id" id="zoneUpazila"><option value="">Select upazila</option><?php foreach($upazilas as $u): ?><option value="<?= $u['id'] ?>" <?= (string)old('upazila_id',$zone['upazila_id']??'')===(string)$u['id']?'selected':'' ?>><?= esc($u['name_en'].' — '.$u['name_bn']) ?></option><?php endforeach ?></select></div><div class="col-md-4"><label class="form-label">Delivery Charge *</label><input class="form-control" type="number" min="0" step=".01" name="delivery_charge" value="<?= esc(old('delivery_charge',$zone['delivery_charge']??'')) ?>" required></div><div class="col-md-4"><label class="form-label">Free Delivery Minimum</label><input class="form-control" type="number" min="0" step=".01" name="free_delivery_minimum" value="<?= esc(old('free_delivery_minimum',$zone['free_delivery_minimum']??'')) ?>"></div><div class="col-md-4"><label class="form-label">Priority</label><input class="form-control" type="number" name="priority" value="<?= esc(old('priority',$zone['priority']??0)) ?>"></div><div class="col-12"><label class="form-label">Estimated Delivery Text</label><input class="form-control" name="estimated_delivery_text" value="<?= esc(old('estimated_delivery_text',$zone['estimated_delivery_text']??'')) ?>" placeholder="e.g. 2–4 working days"></div></div><div class="mt-4"><button class="btn btn-success">Save Zone</button> <a class="btn btn-outline-secondary" href="<?= url_to('admin.delivery') ?>">Cancel</a></div></form><script>const type=document.getElementById('zoneType'),district=document.getElementById('zoneDistrict'),upazila=document.getElementById('zoneUpazila');function fields(){document.querySelectorAll('.location-field').forEach(x=>x.classList.toggle('d-none',type.value==='all_bangladesh'));document.querySelectorAll('.upazila-field').forEach(x=>x.classList.toggle('d-none',type.value!=='upazila'))}type.addEventListener('change',fields);fields();district.addEventListener('change',async()=>{const rows=await fetch('<?= site_url('api/locations/upazilas') ?>/'+district.value).then(r=>r.json());upazila.innerHTML='<option value="">Select upazila</option>'+rows.map(x=>`<option value="${x.id}">${x.name_en} — ${x.name_bn}</option>`).join('')});</script><?= $this->endSection() ?>
